// elfwrite emits a standalone Linux executable whose write(1) syscall is
// generated by nyanjit. The resulting process runs without a Go runtime.
package main

import (
	"fmt"
	"os"
	"runtime"

	"github.com/moriyoshi/nyanjit"
	"github.com/moriyoshi/nyanjit/backend/abi"
	"github.com/moriyoshi/nyanjit/compile"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run() error {
	if runtime.GOOS != "linux" {
		return compile.ErrUnsupported
	}
	path := "./elfwrite"
	if len(os.Args) > 1 {
		path = os.Args[1]
	}
	message := []byte("hello from generated Linux code\n")
	b := nyanjit.NewBuilder()
	writeNumber := uint64(1)
	if runtime.GOARCH == "arm64" || runtime.GOARCH == "riscv64" {
		writeNumber = 64
	}
	number := b.Const(writeNumber)
	fd := b.Const(1)
	buffer := b.Const(readOnlyAddress)
	length := b.Const(uint64(len(message)))
	b.Syscall(number, fd, buffer, length)
	zero := b.Const(0)
	b.Return(zero)
	program, err := b.Finish()
	if err != nil {
		return err
	}
	target, err := compile.NewTarget(compile.TargetSpec{})
	if err != nil {
		return err
	}
	// ContextExternal code runs in another process, so it may make system
	// calls; its template is linked into bytes rather than bound in-process.
	unit, err := compile.Lower(target, program, compile.Func{
		ABI: abi.C, Context: compile.ContextExternal,
		Stack: compile.StackPolicy{Practice: abi.StackPlatform, BytesAvailable: 4096},
	})
	if err != nil {
		return err
	}
	assembly, err := unit.Listing()
	if err != nil {
		return err
	}
	template, err := unit.Template()
	if err != nil {
		return err
	}
	code, err := template.Bytes(nil)
	if err != nil {
		return err
	}
	image, err := encodeExecutable(runtime.GOARCH, code, message)
	if err != nil {
		return err
	}
	if err := os.WriteFile(path, image, 0755); err != nil {
		return err
	}
	return os.WriteFile(path+".s", []byte(assembly), 0644)
}
